package com.lifeos.expenses;import com.lifeos.expenses.dto.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.core.userdetails.UserDetails;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController@RequestMapping("/api/expenses")public class ExpenseController{private final ExpenseService s;public ExpenseController(ExpenseService s){this.s=s;}@GetMapping public List<ExpenseResponse>list(@AuthenticationPrincipal UserDetails p){return s.list(p.getUsername());}@GetMapping("/{id}")public ExpenseResponse get(@PathVariable Long id,@AuthenticationPrincipal UserDetails p){return s.get(id,p.getUsername());}@PostMapping@ResponseStatus(HttpStatus.CREATED)public ExpenseResponse create(@Valid@RequestBody ExpenseRequest r,@AuthenticationPrincipal UserDetails p){return s.create(r,p.getUsername());}@PutMapping("/{id}")public ExpenseResponse update(@PathVariable Long id,@Valid@RequestBody ExpenseRequest r,@AuthenticationPrincipal UserDetails p){return s.update(id,r,p.getUsername());}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@PathVariable Long id,@AuthenticationPrincipal UserDetails p){s.delete(id,p.getUsername());}}
